//! The tool surface, derived from the embedded set: one tool per markdown file.
//!
//! There is no hand-written tool anywhere. Adding a file to `content/` is the whole procedure
//! for adding a tool; the next build embeds it and the next start serves it.

pub mod frontmatter;
pub mod naming;

use std::{collections::HashMap, fmt, sync::LazyLock};

/// Every `.md` under `content/`, as `(set-relative path, text)`, generated by `build.rs`.
pub const EMBEDDED_FILES: &[(&str, &str)] = include!(concat!(env!("OUT_DIR"), "/content_table.rs"));

/// One served file: the tool that serves it, and what it returns.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Instruction {
    /// The tool ID, `lxagents_skills_security_{base}`.
    pub name: String,
    /// The frontmatter `description:`, which is what a client routes on.
    pub description: String,
    /// The set-relative path of the file it serves.
    pub path: &'static str,
    /// The file, whole, frontmatter included, byte-identical to the set.
    pub text: &'static str,
}

/// Why a set cannot be served. Each names the file and the fix.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SurfaceError {
    InvalidName {
        path: String,
        name: String,
    },
    TooLong {
        path: String,
        name: String,
    },
    Collision {
        path: String,
        other: String,
        name: String,
    },
    NoDescription {
        path: String,
    },
    Empty,
}

impl fmt::Display for SurfaceError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::InvalidName { path, name } => write!(
                f,
                "{path} derives the tool name \"{name}\", which is not a valid MCP tool name. Add it to NAME_OVERRIDES."
            ),
            Self::TooLong { path, name } => write!(
                f,
                "{path} derives the tool name \"{name}\", which is over {} characters. Shorten its base in NAME_OVERRIDES.",
                naming::MAX_PUBLISHED_ID_LENGTH
            ),
            Self::Collision { path, other, name } => write!(
                f,
                "{path} and {other} both derive the tool name \"{name}\". One would silently shadow the other; add one to NAME_OVERRIDES."
            ),
            Self::NoDescription { path } => write!(
                f,
                "{path} has no frontmatter `description:`. It would publish as a tool a client cannot route on."
            ),
            Self::Empty => write!(
                f,
                "No markdown files under content/. This server would expose nothing."
            ),
        }
    }
}

impl std::error::Error for SurfaceError {}

/// Build the surface from `(path, text)` pairs, in the order a reader of the set would list them.
///
/// The order is case-insensitive by path, so `SKILL.md` sorts after `references/` the way the
/// TypeScript server listed it, and the tool list a client sees did not move.
pub fn build_surface(
    files: &[(&'static str, &'static str)],
) -> Result<Vec<Instruction>, SurfaceError> {
    let mut ordered: Vec<_> = files.to_vec();
    ordered.sort_by(|(a, _), (b, _)| a.to_lowercase().cmp(&b.to_lowercase()).then(a.cmp(b)));

    let mut claimed: HashMap<String, &str> = HashMap::new();
    let mut surface = Vec::with_capacity(ordered.len());

    for (path, text) in ordered {
        let name = naming::tool_id_for(path);
        if !naming::is_valid_tool_name(&name) {
            return Err(SurfaceError::InvalidName {
                path: path.into(),
                name,
            });
        }
        if name.len() > naming::MAX_PUBLISHED_ID_LENGTH {
            return Err(SurfaceError::TooLong {
                path: path.into(),
                name,
            });
        }
        if let Some(other) = claimed.insert(name.clone(), path) {
            return Err(SurfaceError::Collision {
                path: path.into(),
                other: other.into(),
                name,
            });
        }
        let description = frontmatter::parse(text)
            .and_then(|mut fields| fields.remove("description"))
            .filter(|description| !description.is_empty())
            .ok_or_else(|| SurfaceError::NoDescription { path: path.into() })?;

        surface.push(Instruction {
            name,
            description,
            path,
            text,
        });
    }

    if surface.is_empty() {
        return Err(SurfaceError::Empty);
    }
    Ok(surface)
}

static SURFACE: LazyLock<Result<Vec<Instruction>, SurfaceError>> =
    LazyLock::new(|| build_surface(EMBEDDED_FILES));

/// The embedded set's surface, built once. A binary calls this before serving anything, so a
/// set that cannot be routed on stops the process instead of answering wrongly.
pub fn surface() -> Result<&'static [Instruction], &'static SurfaceError> {
    SURFACE.as_deref()
}

#[cfg(test)]
mod tests {
    use super::*;

    const DOC: &str = "---\nname: a\ndescription: d\n---\n";

    #[test]
    fn the_embedded_set_builds() {
        let surface = surface().expect("the embedded set is valid");
        assert_eq!(surface.len(), 12);
    }

    #[test]
    fn order_is_case_insensitive() {
        let surface = build_surface(&[
            ("SKILL.md", DOC),
            ("references/b.md", DOC),
            ("automation.md", DOC),
        ])
        .unwrap();
        let paths: Vec<_> = surface.iter().map(|i| i.path).collect();
        assert_eq!(paths, ["automation.md", "references/b.md", "SKILL.md"]);
    }

    #[test]
    fn a_collision_is_refused() {
        let error = build_surface(&[("a/x.md", DOC), ("b/x.md", DOC)]).unwrap_err();
        assert!(matches!(error, SurfaceError::Collision { .. }));
    }

    #[test]
    fn a_missing_description_is_refused() {
        let error = build_surface(&[("x.md", "# no frontmatter\n")]).unwrap_err();
        assert_eq!(
            error,
            SurfaceError::NoDescription {
                path: "x.md".into()
            }
        );
        let error = build_surface(&[("x.md", "---\ndescription:\n---\n")]).unwrap_err();
        assert_eq!(
            error,
            SurfaceError::NoDescription {
                path: "x.md".into()
            }
        );
    }

    #[test]
    fn an_invalid_or_long_name_is_refused() {
        let error = build_surface(&[("x.y.md", DOC)]).unwrap_err();
        assert!(matches!(error, SurfaceError::InvalidName { .. }));
        let long = format!("{}.md", "a".repeat(60));
        let long: &'static str = Box::leak(long.into_boxed_str());
        let error = build_surface(&[(long, DOC)]).unwrap_err();
        assert!(matches!(error, SurfaceError::TooLong { .. }));
    }

    #[test]
    fn an_empty_set_is_refused() {
        assert_eq!(build_surface(&[]).unwrap_err(), SurfaceError::Empty);
    }
}
